15	/**
16	 * Zaehler – zählt eine Zahl hoch, sobald sie zur Hälfte im Bild ist.
17	 *
18	 * - Server-HTML enthält bereits den Endwert (SEO, ohne JS korrekt, kein Hydration-Mismatch).
19	 * - Kein Layout-Sprung: Ein unsichtbarer Platzhalter mit dem Endwert reserviert die Breite.
20	 * - Kein React-Rendern pro Frame: Die Ziffern werden direkt per rAF ins DOM geschrieben.
21	 * - Reduzierte Bewegung, schon vorbeigescrollt oder Wert 0 → steht sofort auf dem Endwert.
22	 * - Ändert sich `wert` später (z. B. Rechner), springt die Anzeige ohne erneutes Zählen.
23	 *
24	 * NUR Werte zählen, die ohnehin auf der Seite stehen (kein erfundener Social Proof,
25	 * keine Live-Zähler).
26	 *
27	 * @param {object} p
28	 * @param {number} p.wert              Endwert (Zahl, nicht String).
29	 * @param {number} [p.nachkomma=0]     Nachkommastellen.
30	 * @param {string} [p.vor]             Text davor, z. B. "+" oder "€ ".
...
33	 * @param {string} [p.sprache="de-DE"] Zahlenformat (en/*: "en-GB").
34	 * @param {string} [p.className]
35	 *
36	 * @example
37	 * <p className="ov-kpi-l"><Zaehler wert={48.6} nachkomma={1} nach=" MWp" /></p>
38	 */
39	export default function Zaehler({ wert, nachkomma = 0, vor = "", nach = "", dauer = 1400, verzoegerung = 0, sprache = "de-DE", className }) {
40	  const ref = useRef(null);
41	  const gezaehlt = useRef(false); // nur der erste Eintritt zählt – spätere Wertänderungen springen direkt
42	  const ziel = Number(wert) || 0;
43	  const fmt = format(sprache, nachkomma);
44	  const endText = `${vor}${fmt.format(ziel)}${nach}`;
45	
46	  useEffect(() => {
47	    const el = ref.current;
48	    if (!el || !ziel || gezaehlt.current || typeof IntersectionObserver === "undefined") return undefined;
49	    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return undefined;
50	
51	    let raf = 0;
52	    let timer = 0;
53	    // Den von React verwalteten Textknoten beschreiben (nicht ersetzen), damit
54	    // spätere Re-Renders ihn weiter aktualisieren können.
55	    const knoten = el.firstChild;
56	    const setzen = (text) => {
57	      if (knoten) knoten.nodeValue = text;
58	    };
59	    const schreiben = (v) => setzen(`${vor}${fmt.format(v)}${nach}`);
60	    const io = new IntersectionObserver(
61	      ([e]) => {
62	        if (!e.isIntersecting) return;
63	        io.disconnect();
64	        gezaehlt.current = true;
65	        schreiben(0);
66	        timer = setTimeout(() => {
67	          const start = performance.now();
68	          const schritt = (t) => {
69	            const p = Math.min((t - start) / dauer, 1);
70	            // expo-out: schnell los, weich ankommen
71	            const k = p === 1 ? 1 : 1 - Math.pow(2, -10 * p);
72	            schreiben(ziel * k);
73	            if (p < 1) raf = requestAnimationFrame(schritt);
74	            else setzen(endText);
75	          };
76	          raf = requestAnimationFrame(schritt);
77	        }, verzoegerung);
78	      },
79	      { threshold: 0.5 }
80	    );
81	    // Schon oberhalb des Viewports (Zurück-Navigation)? Dann nicht mehr zählen.
82	    if (el.getBoundingClientRect().bottom > 0) io.observe(el);
83	    return () => {
84	      io.disconnect();
85	      clearTimeout(timer);
86	      cancelAnimationFrame(raf);
